define(["app", "i18nkeys"], function(CandidateManager, i18nkeys){
    CandidateManager.module("Entities", function(Entities, CandidateManager, Backbone, Marionette, $, _){


        /* i18nkeys initialization */
        var i18nKeysvalue = new i18nkeys.i18nEntity();
        var lang = i18nKeysvalue.get('candidatelang');

        Entities.Job = Backbone.Model.extend({
            url: "candidatejobdetail",
            parse: function(response){
                return response;
            }
        });

        Entities.JobCollection = Backbone.Collection.extend({
            url: "candidatejobsearchpage",
            parse: function(response){
                return response;
            },
            model: Entities.Job
        });

        Entities.JobSearchResult = Backbone.Model.extend({
            url: "candidatejobsearch",
            parse: function(response){
                return response;
            }
        });

        Entities.CandidateMessage = Backbone.Model.extend({
            url: "candidategetmessages",
            parse: function(response){
                return response;
            }
        });

        Entities.MessagingStatus = Backbone.Model.extend({
            url: "getmessagingstatus",
            parse: function(response){
                return response;
            }
        });

        var API = {

            getJobSearchResult: function(params){
                var jobs = new Entities.JobSearchResult();
                var defer = $.Deferred();
                jobs.fetch({
                    method: 'post',
                    'Accept': 'application/json',
                    'Content-type' : "application/json; charset=utf-8 ",
                    data :{"careerSiteUrlParams": JSON.stringify(params), "lang": lang },
                    success: function(data){
                        var jobCollection = new Entities.JobCollection();
                        jobCollection.add(data.get('jobVoList'));
                        data.set('jobCollection', jobCollection);
                        defer.resolve(data);
                    },
                    cache:true
                });
                return defer.promise();

            },
            getJobEntityById: function(token, jobId, source){
                var job = new Entities.Job({id: jobId});
                var defer = $.Deferred();
                job.fetch({
                    data:{token:token, jobSeq:jobId, source:source, lang: lang },
                    success: function(resp){
                        defer.resolve(resp);
                    },
                    error: function(resp){
                        defer.resolve(undefined);
                    },
                    cache:false
                });
                return defer.promise();
            },
            getJobEntityByToken: function(token){
                var job = new Entities.Job({id: token});
                var defer = $.Deferred();
                job.fetch({
                    data:{token:token, lang: lang },
                    success: function(resp){
                        defer.resolve(resp);
                    },
                    error: function(resp){
                        defer.resolve(undefined);
                    },
                    cache:false
                });
                return defer.promise();
            },
            getJobsListPage: function(params){
                var jobs = new Entities.JobCollection();
                var defer = $.Deferred();
                jobs.fetch({
                    method: 'post',
                    'Accept': 'application/json',
                    'Content-type' : "application/json; charset=utf-8 ",
                    data :{"careerSiteUrlParams": JSON.stringify(params), "lang": lang },
                    success: function(data){
                        defer.resolve(data);
                    },
                    cache:false
                });
                return defer.promise();

            },
            getMessagesPage: function(token, emplRefrlSeq, candMessage){
                var jobs = new Entities.CandidateMessage({id: emplRefrlSeq});
                var defer = $.Deferred();
                jobs.fetch({
                    data:{token: token, emplRefrlSeq:emplRefrlSeq, candMessage: candMessage, lang: lang },
                    success: function(data){
                        defer.resolve(data);

                    },
                    cache:false
                });
                return defer.promise();

            },
            getMessagingStatus: function(emplRefrlSeq){
                var jobs = new Entities.MessagingStatus();
                var defer = $.Deferred();
                jobs.fetch({
                    data:{emplRefrlSeq:emplRefrlSeq, lang: lang },
                    success: function(data){
                        defer.resolve(data);
                    },
                    cache:false
                });
                return defer.promise();
            }

        };

        CandidateManager.reqres.setHandler("job:entityByTokenJobSeq", function(token,id,source){
            return API.getJobEntityById(token, id, source);
        });
        CandidateManager.reqres.setHandler("job:entityByToken", function(id){
            return API.getJobEntityByToken(id);
        });
        CandidateManager.reqres.setHandler("job:allentities", function(params){
            return API.getJobSearchResult(params);
        });
        CandidateManager.reqres.setHandler("job:page", function(params){
            return API.getJobsListPage(params);
        });
        CandidateManager.reqres.setHandler("candidate:messaging", function(token, emplRefrlSeq, candMessage){
            return API.getMessagesPage(token, emplRefrlSeq, candMessage);
        });
        CandidateManager.reqres.setHandler("candidate:messagingstatus", function(emplRefrlSeq){
            return API.getMessagingStatus(emplRefrlSeq);
        });
    });

    return ;
});

define(["app", "apps/candidates/view/candidatejoblistlayout_view",
        "apps/candidates/view/breadcrumbpanel_view", "apps/candidates/view/bannerpanel_view", "apps/candidates/view/bannersearchpanel_view",
        "apps/candidates/view/searchpanel_view", "apps/candidates/view/filterpanel_view",
        "apps/candidates/view/jobbasicdescription_view", "apps/candidates/view/candidateemailshare_view", "apps/candidates/view/candidatejobfilter_view",
        "apps/candidates/view/model_region", "validator","i18nkeys", "bootstrap","multiselect", "loadmask"],
    function (CandidateManager, Dashboard, BreadcrumbPanel, BannerPanel, BannerSearchPanel,
              SearchPanel, FilterPanel, BasicDescription, Emailshare, JobFilter, ModalRegion, Validator, i18nkeys) {
        CandidateManager.module("CandidatesApp.Joblist", function (Joblist, CandidateManager, Backbone, Marionette, $, _) {
            Joblist.Controller = {
                listJobs: function (token, source, campaignSeq, params, validUrlParams) {
                    if (source && (source === 'AGENCY' || source === 'CAMPUS')) {
                        CandidateManager.trigger("candidate:pagenotfound");
                    }
                    require(["entities/job", "entities/company"], function () {

                        /* Params initializations */
                        var companyInfo, docData;
                        var onOff = new Object();
                        var initParams = new Object();

                        /* Views initialization */
                        var candidateDashboard = new Dashboard.Layout();

                        /* Validators initialization */
                        var emailShareModel = new Validator.Validator();

                        /* i18nkeys initialization */
                        var i18nKeys = new i18nkeys.i18nEntity();

                        /* Request for company info */
                        var companyModel = CandidateManager.request("company:entityByToken", token, source);

                        $.when(companyModel).done(function (company) {
                            //set company info i18next keys
                            company.set('i18nextKeys', i18nKeys.get('companyinfotpl'));
                            companyInfo = company;
                            onOff = companyInfo.attributes.config;
                            filterJobs(initParams, true);
                        });

                        /* Google Analytics push */
                        var name = getRefValue() + " " + "Joblist";
                        ga('send', 'event', name);

                        $('.wrapper').unmask();
                        $('.wrapper').removeClass('page-height');
                        $('.wrapper').scrollTop(0);

                        /* Adding default params for search */
                        initParams.page = 0;
                        initParams.search = "*:*";
                        initParams.campaignSeq = campaignSeq;
                        initParams.token = token;
                        initParams.source = source;
                        initParams.pagesize = 10;

                        /* Extending params into initParams */
                        if (!_.isEmpty(params)) {
                            _.extend(initParams, _.pick(params, "page", "search", "location","state", "exp", "source", "department", "bu","businessunit", "acc", "function", "jobSeq", "geo", "level", 'emptype'))
                        }

                        /* Set template for view and invoke show */
                        var candidateDashboardPromise = candidateDashboard.setTemplate();
                        candidateDashboardPromise.done(function () {
                            CandidateManager.bodyRegion.show(candidateDashboard);
                        });

                        /* Method for job filter */
                        var filterJobs = function (params, skipLoading) {

                            if (!skipLoading) {
                                $('#search-panel').mask();
                                $('#job-listing').mask("");
                            }
                            $('.js-joblist-viewmore').hide();

                            jobDashboardModel = CandidateManager.request("job:allentities", params);

                            $.when(jobDashboardModel).done(function (joblistPage) {
                                if (!joblistPage) {
                                    CandidateManager.trigger("candidate:pagenotfound");
                                } else {

                                    var jobCollection = joblistPage.get('jobCollection');

                                    var joblist = new BasicDescription.JobList({collection: jobCollection});

                                    joblist.on("childview:navigatetodesc:show", function (childView, args) {
                                        var jobSeqNew = childView.model.toJSON().jobSeq;
                                        CandidateManager.trigger("jobdescriptionforjob:show", token, source, jobSeqNew);
                                    });

                                    joblist.on("childview:directjobapplyshow", function (childView) {
                                        var jobSeqNew = childView.model.toJSON().jobSeq;
                                        CandidateManager.trigger("jobapplication:show", token, jobSeqNew);
                                    });

                                    joblist.on("childview:getCompanyInfo", function (childView) {
                                        childView.model.set("companyVO", companyInfo.toJSON());
                                    });

                                    var searchData = joblistPage;
                                    var selectedLocation = '';
                                    if (typeof initParams.location !== 'undefined') {
                                        selectedLocation = initParams.location.split('+');
                                    }
                                    var exp = '';
                                    if (typeof initParams.exp !== 'undefined') {
                                        exp = initParams.exp;
                                    }

                                    var search = initParams.search;
                                    if (search === '*:*') {
                                        search = '';
                                    }

                                    var selectedDepartment = '';
                                    if (typeof initParams.department !== 'undefined') {
                                        selectedDepartment = initParams.department.split("+");
                                    }

                                    var selectedBu = '';
                                    if (typeof initParams.bu !== 'undefined') {
                                        selectedBu = initParams.bu.split("+");
                                    }
                                    var selectedBusinessUnit = '';
                                    if (typeof initParams.businessunit !== 'undefined') {
                                        selectedBusinessUnit = initParams.businessunit.split("+");
                                    }
                                    var selectedState = '';
                                    if (typeof initParams.state !== 'undefined') {
                                        selectedState = initParams.state.split("+");
                                    }

                                    var selectedAcc = '';
                                    if (typeof initParams.acc !== 'undefined') {
                                        selectedAcc = initParams.acc.split("+");
                                    }

                                    var jobFunction = '';
                                    if (typeof initParams.function !== 'undefined') {
                                        jobFunction = initParams.function.split("+");
                                    }

                                    searchData.set("locations", selectedLocation);
                                    searchData.set("search", search);
                                    searchData.set("exp", exp);
                                    searchData.set("departments", selectedDepartment);
                                    searchData.set("businessUnits", selectedBu);
                                    searchData.set("businessunit", selectedBusinessUnit);
                                    searchData.set("states", selectedState);
                                    searchData.set("accounts", selectedAcc);
                                    searchData.set("jobFunction", jobFunction);
                                    searchData.set('i18nextKeys', i18nKeys.get('joblistpage'));

                                    CandidateManager.trigger("job:updateurl", params);

                                    //seo fix
                                    docData = {
                                        companyName: companyInfo.get("companyName"),
                                        jobCount: searchData.get("totalJobCount"),
                                        jobLocations: function () {
                                            if (searchData.get("locations") != "" && searchData.get("locations") != null) {
                                                return searchData.get("locations");
                                            } else {
                                                return _.map(searchData.get("cityCount"), function (value) {
                                                    return value.split('+')[0];
                                                }).toString();
                                            }
                                        }
                                    };
                                    CandidateManager.trigger("document:updateTitleDesc", docData, 'listing');
                                    /* Views initialization */

                                    var bannerPanel = new BannerPanel.BannerPanel({model: companyInfo});
                                    bannerPanel.model.set("totalJobCount", searchData.get("totalJobCount"));

                                    var filterPanel = new FilterPanel.FilterPanel({model: searchData});
                                    filterPanel.model.set("config", companyInfo.get("config"));
                                    var searchPanel = new SearchPanel.SearchPanel({model: searchData});

                                    /* Set template for view and invoke show */
                                    if ('breadcrumb_region' in CandidateManager.defaultConfig.get("config")) {
                                        var breadCrumbPanel = new BreadcrumbPanel.BreadcrumbPanel();
                                        var breadcrumbPromise = breadCrumbPanel.setTemplate();
                                        breadcrumbPromise.done(function () {
                                            candidateDashboard.breadcrumbRegion.show(breadCrumbPanel);
                                        });
                                    }


                                    var bannerPromise = bannerPanel.setTemplate();
                                    bannerPromise.done(function () {
                                        candidateDashboard.bannerRegion.show(bannerPanel);
                                    });

                                    if ('banner_search_region' in CandidateManager.defaultConfig.get("config")) {
                                        var bannerSearchPanel = new BannerSearchPanel.BannerSearchPanel({model: searchData});
                                        var bannerSearchPromise = bannerSearchPanel.setTemplate();
                                        bannerSearchPromise.done(function () {
                                            candidateDashboard.bannerSearchRegion.show(bannerSearchPanel);
                                        });

                                        bannerSearchPanel.on("filterJobs", function (page, search, location, exp, jobFunction) {
                                            defaultSearch(page, search, location, exp, jobFunction);
                                        });
                                    }
                                    var searchPromise = searchPanel.setTemplate();
                                    searchPromise.done(function () {
                                        candidateDashboard.searchRegion.show(searchPanel);
                                    });
                                    var filterPromise = filterPanel.setTemplate();
                                    filterPromise.done(function () {
                                        candidateDashboard.filterRegion.show(filterPanel);
                                    });

                                    var jobPromise = joblist.setTemplate();
                                    $.when(jobPromise).done(function () {
                                        candidateDashboard.joblistRegion.show(joblist);
                                    });

                                    var FooterModel = Backbone.Model.extend();
                                    var footerModel = new FooterModel();
                                    footerModel.set("jobCount",  searchData.attributes.allActiveJobCount);
                                    footerModel.set('viewmore', jobCollection.length < searchData.attributes.totalJobCount);
                                    footerModel.set('viewall', params.jobSeq && params.jobSeq != "" );
                                    footerModel.set('i18nextKeys', i18nKeys.get('joblistfooter'));
                                    /* Views initialization */
                                    var listFooterPanel = new BasicDescription.JobListFooter({model:footerModel});
                                    /* Set template for view and invoke show */
                                    var listFooterPromise = listFooterPanel.setTemplate();
                                    listFooterPromise.done(function () {
                                        candidateDashboard.joblistfooterRegion.show(listFooterPanel);
                                    });

                                    listFooterPanel.on("fetchMoreJobs", function () {
                                        initParams.page++;
                                        var nextPageModel = CandidateManager.request("job:page", initParams);
                                        $.when(nextPageModel).done(function (nextPage) {
                                                jobCollection.add(nextPage.models);
                                                $('.js-joblist-loadingmore').hide();
                                                if (jobCollection.length < searchData.attributes.totalJobCount && nextPage.models.length > 0) {
                                                    listFooterPanel.pageprocessing = false;
                                                    $('.js-joblist-viewmore').show();
                                                }
                                        });
                                    });

                                    $('#search-panel').unmask();
                                    $('#job-listing').unmask("");

                                    joblist.on("childview:emailShare", function (childView) {
                                        emailShareModel.set(childView.model.toJSON());
                                        var emailShare = new Emailshare.Email({model: emailShareModel});
                                        candidateDashboard.modalRegion.show(emailShare);
                                        Backbone.Validation.bind(emailShare);
                                    });

                                    searchPanel.on("mobilejobfilter", function () {
                                        var FilterModel = Backbone.Model.extend();
                                        var filterModel = new FilterModel();
                                        filterModel.set("cityCount", searchData.toJSON().cityCount);
                                        filterModel.set('i18nextKeys', i18nKeys.get('mobilejobfilter'));
                                        filterModel.set("selectedCities", searchData.toJSON().locations);
                                        filterModel.set("selectedExp", searchData.toJSON().exp);

                                        var jobFilter = new JobFilter.JobFilterPanel({model: filterModel});
                                        candidateDashboard.modalRegion.show(jobFilter);
                                        jobFilter.on("filterJobs", function (page, search, location, exp) {
                                            initParams.token = token;
                                            initParams.page = page;
                                            if (search == '' || typeof search === 'undefined') {
                                                search = "*:*";
                                            }
                                            initParams.search = search;
                                            var locations = "";
                                            if (location !== '' && location != null) {
                                                for (var i = 0; i < location.length; i++) {
                                                    locations = locations + location[i];
                                                    if (i < (location.length - 1)) {
                                                        locations = locations + '+';
                                                    }
                                                }
                                            }
                                            initParams.location = locations;
                                            initParams.exp = exp;

                                            filterJobs(initParams);
                                        });
                                    });

                                    searchPanel.on("filterJobs", function (page, search, location, exp, jobFunction) {
                                        defaultSearch(page, search, location, exp, jobFunction);
                                    });


                                    filterPanel.on("removelocation", function (removelocation) {
                                        var arr = initParams.location.split('+');
                                        var index = arr.indexOf(removelocation);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        // arr.pop(removelocation);
                                        var locations = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                locations = locations + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    locations = locations + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.location = locations;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removeexp", function (removelocation) {
                                        initParams.exp = '';
                                        initParams.page = 0;
                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("clearfilters", function (removelocation) {
                                        initParams.location = '';
                                        initParams.exp = '';
                                        initParams.search = "*:*";
                                        initParams.department = '';
                                        initParams.businessunit = '';
                                        initParams.bu = '';
                                        initParams.state = '';
                                        initParams.acc = '';
                                        initParams.function = '';
                                        initParams.page = 0;
                                        filterJobs(initParams);
                                    });
                                    filterPanel.on("removekeyword", function (removelocation) {
                                        initParams.search = "*:*";
                                        initParams.page = 0;
                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removedept", function (removedept) {
                                        var arr = initParams.department.split('+');
                                        var index = arr.indexOf(removedept);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        // arr.pop(removedept);
                                        var departments = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                departments = departments + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    departments = departments + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.department = departments;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removestate", function (removestate) {
                                        var arr = initParams.state.split('+');
                                        var index = arr.indexOf(removestate);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        // arr.pop(removestate);
                                        var states = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                states = states + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    states = states + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.state = states;

                                        filterJobs(initParams);
                                    });


                                    filterPanel.on("removebusinessunit", function (removebusinessunit) {
                                        var arr = initParams.businessunit.split('+');
                                        var index = arr.indexOf(removebusinessunit);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        // arr.pop(removestate);
                                        var businessunits = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                businessunits = businessunits + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    businessunits = businessunits + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.businessunit = businessunits;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removebu", function (removebu) {
                                        var arr = initParams.bu.split('+');
                                        var index = arr.indexOf(removebu);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        // arr.pop(removebu);
                                        var businessUnits = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                businessUnits = businessUnits + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    businessUnits = businessUnits + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.bu = businessUnits;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removeacc", function (removeacc) {
                                        var arr = initParams.acc.split('+');
                                        var index = arr.indexOf(removeacc);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        //arr.pop(removeacc);
                                        var accounts = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                accounts = accounts + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    accounts = accounts + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.acc = accounts;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("removejobfn", function (jobfn) {
                                        var arr = initParams.function.split('+');
                                        var index = arr.indexOf(jobfn);
                                        if (index > -1) {
                                            arr.splice(index, 1);
                                        }
                                        var jobfunctions = "";
                                        if (arr !== '' && arr != null) {
                                            for (var i = 0; i < arr.length; i++) {
                                                jobfunctions = jobfunctions + arr[i];
                                                if (i < (arr.length - 1)) {
                                                    jobfunctions = jobfunctions + '+';
                                                }
                                            }
                                        }

                                        initParams.page = 0;
                                        initParams.function = jobfunctions;

                                        filterJobs(initParams);
                                    });

                                    filterPanel.on("jobapplyctp", function (jobSeq) {
                                        CandidateManager.trigger("jobapplication:show", token, onOff.ctpJobSeq);
                                    });

                                    if ('side_region' in CandidateManager.defaultConfig.get("config")) {
                                        require(["apps/candidates/view/candidatecompanyinfo_view"], function (Sidepanel) {

                                            var sidepanel = new Sidepanel.CompanyInfo({model: companyInfo});
                                            var sidePromise = sidepanel.setTemplate();
                                            sidePromise.done(function () {
                                                candidateDashboard.sideRegion.show(sidepanel);
                                            });
                                            sidepanel.on("jobapplyctp", function (jobSeq) {
                                                CandidateManager.trigger("jobapplication:show", token, onOff.ctpJobSeq);
                                            });

                                        });
                                    }

                                    CandidateManager.trigger("onlyonce");
                                }
                            });
                        };

                        var defaultSearch = function (page, search, location, exp, jobFunction) {
                            initParams.token = token;
                            initParams.page = page;
                            if (search == '' || typeof search === 'undefined') {
                                search = "*:*";
                            }

                            initParams.search = search;
                            var locations = "";
                            if (location !== '' && location != null) {
                                for (var i = 0; i < location.length; i++) {
                                    locations = locations + location[i];
                                    if (i < (location.length - 1)) {
                                        locations = locations + '+';
                                    }
                                }
                            }
                            initParams.location = locations;
                            initParams.exp = exp;

                            var jobFunctions = "";
                            if (jobFunction !== '' && jobFunction != null) {
                                for (var i = 0; i < jobFunction.length; i++) {
                                    jobFunctions = jobFunctions + jobFunction[i];
                                    if (i < (jobFunction.length - 1)) {
                                        jobFunctions = jobFunctions + '+';
                                    }
                                }
                            }
                            initParams.function = jobFunctions;

                            filterJobs(initParams);
                        }
                    });
                }
            }
        });
        return CandidateManager.CandidatesApp.Joblist.Controller;
    });

define(["app", "tpl!apps/candidates/template/jobdashboard/jobbasicdescription.tpl",
        "tpl!apps/candidates/template/jobdashboard/r1/jobbasicdescription.tpl", "tpl!apps/candidates/template/jobdashboard/NoJobs.tpl", "i18nkeys", "sharescript"],
    function (CandidateManager, jobDesc, jobDescNew, noJobsTpl, i18nkeys) {
        CandidateManager.module("CandidatesApp.JobBasicDesc.View", function (View, CandidateManager, Backbone, Marionette, $, _) {

            /* i18nkeys initialization */
            var i18nKeys = new i18nkeys.i18nEntity();

            View.JobDesc = Marionette.ItemView.extend({
                template: jobDesc,
                tagName: "li",
                className: "row bt-gray-border job list-arrow white-bg",
                id: "row",
                events: {
                    "click .close": "closemodal",
                    "click .mobile-share-area": "toggleshare",
                    "click .share-area": "stopBubble",
                    "mouseenter .share-area": "openshare",
                    "mouseleave .share-area": "closeshare",
                    "mouseenter": "joblisthover",
                    "mouseleave": "joblistleave",
                    "click .js-facebook-share": "shareonfacebook",
                    "click .js-linkedin-share": "shareonlinkedin",
                    "click .js-whatsapp-share": "shareonwhatsapp",
                    "click .js-twitter-share": "shareontwitter",
                    "click .js-email-share": "shareonemail",
                    "click .js-direct-job-application": "directjobapply",
                    "click": "titlenavigatetodesc"
